?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galería · EventQR</title><link rel="stylesheet" href="/assets/style.css"></head><body class="admin"><header class="topbar"><a class="brand" href="/events.php">Event<span>QR</span></a><a href="/events.php">Volver a eventos</a></header><main class="container"><h1><?= e($event['nombre']) ?></h1><p class="muted"><?= count($photos) ?> fotografías</p><div class="gallery"><?php foreach ($photos as $photo): ?><article class="photo-card"><img src="/photo.php?id=<?= (int)$photo['id'] ?>" alt="Fotografía subida" loading="lazy"><div class="photo-meta"><span><?= e($photo['nombre_original']) ?><br><?= number_format((int)$photo['bytes']/1048576, 1) ?> MB</span><a class="button secondary" href="/photo.php?id=<?= (int)$photo['id'] ?>&download=1">Descargar original</a><form method="post" onsubmit="return confirm('¿Eliminar esta fotografía?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="photo_id" value="<?= (int)$photo['id'] ?>"><button class="button danger">Eliminar</button></form></div></article><?php endforeach; ?></div></main></body></html>
